def g(*c):
    try: return subprocess.check_output(c, text=True, cwd=F.FT.ROOT).strip()
    except Exception: return None
json.dump(dict(step='45F', git_head_at_report=g('git', 'rev-parse', '--short', 'HEAD'), prereg_commit='ca9bf2d', python=platform.python_version(), platform=platform.platform(), date=time.strftime('%Y-%m-%d'), bootstrap='group, 1000 resamples, seed 0', status='INCOMPLETE (2 h cap)' if inc else 'complete', numbers_meet_rule=bool(ps['passed']), judge='mlx-community/gemma-2-9b-it-4bit, frozen prompt_v2, greedy'), open(F.P('run_info.json'), 'w'), indent=1)
